// Generated by OrchestKit Claude Plugin
// Created: 2026-09-19
//
// "Related pages" block for skill / agent / hook reference pages.
//
// Deterministic scorer over the internal link graph (lib/generated/related-graph,
// rebuilt by scripts/gen-related-graph.mjs from scripts/seo/link-graph.mjs):
//
//   same collection            +1   (skill<->skill reads better than skill<->hook)
//   same category              +4   (skill by-category bucket / agent category / hook phase)
//   shared tag, max 3          +2 each  (skill tags, agent keywords; hooks untagged)
//   mutual content references  +3   (A links B and B links A)
//   one-way content reference  +1
//   orphan target (0 inbound)  +2   (the audit's orphans get links first)
//
// Order: score desc, then inbound asc (weaker-linked pages first), then url asc.
// 3-5 links per page; if fewer than 3 candidates score > 0 the remainder is
// padded from same-kind pages by weakest inbound so every reference page
// renders a useful block.
//
// Optional Jev re-rank (TypeSafe System One, model jev-latest) runs ONLY when
// ORK_SITE_JEV_RERANK is truthy and TYPESAFE_API_KEY is present: one request
// per page at build time reorders the candidate shortlist. Any failure (no
// key, 3s timeout, HTTP error, malformed answer) keeps the deterministic
// order. With the flag off the code path performs zero network calls.

import { SKILLS } from "@/lib/generated/skills-data";
import { AGENTS } from "@/lib/generated/agents-data";
import { HOOK_PHASES } from "@/lib/hook-phases";
import { RELATED_GRAPH, type RelatedGraphData } from "@/lib/generated/related-graph";

export type RefKind = "skill" | "agent" | "hook";
export type RelatedItem = { url: string; title: string };

export type RelatedCandidate = {
	url: string;
	title: string;
	kind: RefKind;
	category: string | null;
	tags: readonly string[];
	inbound: number;
};

const JEV_ENDPOINT = "https://api.typesafe.ai/v1/systemone";
const JEV_TIMEOUT_MS = 3000;
const JEV_CANDIDATE_LIMIT = 8;

const WEIGHTS = {
	sameKind: 1,
	sameCategory: 4,
	sharedTag: 2,
	sharedTagCap: 3,
	mutualRef: 3,
	oneWayRef: 1,
	orphanTarget: 2,
} as const;

/** `/docs/reference/<kind>/<slug>` -> kind, or null for non-reference pages. */
export function refKindOf(url: string): RefKind | null {
	const m = /^\/docs\/reference\/(skills|agents|hooks)\/(.+)$/.exec(url);
	if (!m) return null;
	if (m[2] === "index") return null;
	return m[1] === "skills" ? "skill" : m[1] === "agents" ? "agent" : "hook";
}

/** Last URL segment(s) under reference/<kind>/, e.g. "spotlights/foo" or "foo". */
function refSlugOf(url: string): string {
	const m = /^\/docs\/reference\/(?:skills|agents|hooks)\/(.+)$/.exec(url);
	return m?.[1] ?? "";
}

// ---------------------------------------------------------------------------
// Candidate pool (built once per process; all inputs are build-time static).
// ---------------------------------------------------------------------------

/** skill url -> category slug, derived from the by-category index pages' edges
 * in the link graph (the same source of truth the audit uses). */
function skillCategoryMap(graph: RelatedGraphData): Map<string, string> {
	const map = new Map<string, string>();
	for (const [from, targets] of Object.entries(graph.out)) {
		const cat = /^\/docs\/skills\/by-category\/(.+)$/.exec(from)?.[1];
		if (!cat) continue;
		for (const to of targets) {
			if (refKindOf(to) !== "skill") continue;
			if (!map.has(to)) map.set(to, cat); // first wins; urls are sorted
		}
	}
	return map;
}

function hookCategoryOf(slug: string): string {
	if (slug.startsWith("spotlights/")) return "spotlights";
	for (const phase of HOOK_PHASES) {
		if (phase.slugs.includes(slug)) return phase.id;
	}
	return "other";
}

let cachedPool: RelatedCandidate[] | null = null;

export function candidatePool(graph: RelatedGraphData = RELATED_GRAPH): RelatedCandidate[] {
	if (graph === RELATED_GRAPH && cachedPool) return cachedPool;

	const skillCats = skillCategoryMap(graph);
	const agentById = new Map(AGENTS.map((a) => [a.id, a]));
	const pool: RelatedCandidate[] = [];

	for (const [url, meta] of Object.entries(graph.pages)) {
		const kind = refKindOf(url);
		if (!kind) continue;
		const slug = refSlugOf(url);
		let category: string | null = null;
		let tags: readonly string[] = [];
		if (kind === "skill") {
			category = skillCats.get(url) ?? null;
			tags = SKILLS[slug]?.tags ?? [];
		} else if (kind === "agent") {
			const agent = agentById.get(slug);
			category = agent?.category ?? null;
			tags = agent?.keywords ?? [];
		} else {
			category = hookCategoryOf(slug);
		}
		pool.push({ url, title: meta.title, kind, category, tags, inbound: meta.inbound });
	}
	pool.sort((a, b) => a.url.localeCompare(b.url));
	if (graph === RELATED_GRAPH) cachedPool = pool;
	return pool;
}

// ---------------------------------------------------------------------------
// Deterministic scorer.
// ---------------------------------------------------------------------------

export function scoreCandidate(
	page: RelatedCandidate,
	cand: RelatedCandidate,
	graph: RelatedGraphData,
): number {
	let score = 0;
	if (page.kind === cand.kind) {
		score += WEIGHTS.sameKind;
		if (page.category !== null && page.category === cand.category) {
			score += WEIGHTS.sameCategory;
		}
	}
	const shared = page.tags.filter((t) => cand.tags.includes(t)).length;
	score += WEIGHTS.sharedTag * Math.min(shared, WEIGHTS.sharedTagCap);

	const out = graph.out[page.url]?.includes(cand.url) ?? false;
	const inn = graph.out[cand.url]?.includes(page.url) ?? false;
	if (out && inn) score += WEIGHTS.mutualRef;
	else if (out || inn) score += WEIGHTS.oneWayRef;

	// Orphan bonus only stacks on a real relevance signal: without this guard
	// every zero-inbound page would outrank weak but relevant same-kind pages.
	if (score > 0 && cand.inbound === 0) score += WEIGHTS.orphanTarget;
	return score;
}

function byRank(graph: RelatedGraphData) {
	return (a: { cand: RelatedCandidate; score: number }, b: { cand: RelatedCandidate; score: number }) =>
		b.score - a.score ||
		a.cand.inbound - b.cand.inbound ||
		a.cand.url.localeCompare(b.cand.url);
}

/**
 * The deterministic Related list: top `max` scoring candidates, padded to
 * `min` from same-kind pages (weakest inbound first) when scores run dry.
 */
export function deterministicRelated(
	page: RelatedCandidate,
	pool: readonly RelatedCandidate[],
	graph: RelatedGraphData,
	{ min = 3, max = 5 }: { min?: number; max?: number } = {},
): RelatedCandidate[] {
	const scored = pool
		.filter((c) => c.url !== page.url)
		.map((cand) => ({ cand, score: scoreCandidate(page, cand, graph) }))
		.filter((x) => x.score > 0)
		.sort(byRank(graph));

	const picked = scored.slice(0, max).map((x) => x.cand);
	if (picked.length < min) {
		const chosen = new Set(picked.map((c) => c.url));
		const fill = pool
			.filter(
				(c) => c.kind === page.kind && c.url !== page.url && !chosen.has(c.url),
			)
			.sort((a, b) => a.inbound - b.inbound || a.url.localeCompare(b.url));
		picked.push(...fill.slice(0, min - picked.length));
	}
	return picked;
}

// ---------------------------------------------------------------------------
// Jev re-rank (flag-gated).
// ---------------------------------------------------------------------------

export function jevRerankEnabled(env: NodeJS.ProcessEnv = process.env): boolean {
	return ["1", "true", "yes", "on"].includes(
		String(env.ORK_SITE_JEV_RERANK ?? "").toLowerCase(),
	);
}

type JevDeps = {
	fetchImpl?: typeof fetch;
	apiKey?: string;
	timeoutMs?: number;
};

/**
 * One System One request: a Choice question whose options are the candidate
 * URLs; the returned probability distribution reorders the whole shortlist.
 * Returns null on ANY failure so the caller keeps the deterministic order.
 */
export async function jevRerankOrder(
	page: { url: string; title: string },
	candidates: readonly RelatedItem[],
	deps: JevDeps = {},
): Promise<string[] | null> {
	const fetchImpl = deps.fetchImpl ?? fetch;
	const apiKey = deps.apiKey ?? process.env.TYPESAFE_API_KEY;
	if (!apiKey) return null;
	const timeoutMs = deps.timeoutMs ?? JEV_TIMEOUT_MS;

	const body = {
		state: {
			currentPage: { url: page.url, title: page.title },
			candidates: candidates.map((c) => ({ url: c.url, title: c.title })),
		},
		model: "jev-latest",
		questions: {
			pick: {
				type: "choice",
				instructions:
					"Which candidate docs page is most useful to a reader who just finished the current page?",
				criteria: Object.fromEntries(
					candidates.map((c) => [c.url, `${c.title} (${c.url})`]),
				),
			},
		},
	};

	let json: unknown;
	try {
		const res = await fetchImpl(JEV_ENDPOINT, {
			method: "POST",
			headers: {
				Authorization: `Bearer ${apiKey}`,
				"Content-Type": "application/json",
			},
			body: JSON.stringify(body),
			signal: AbortSignal.timeout(timeoutMs),
		});
		if (!res.ok) return null;
		json = await res.json();
	} catch {
		return null;
	}

	const answer = (json as { answers?: { pick?: unknown } })?.answers?.pick;
	const probs = (answer as { type?: string; probabilities?: Record<string, unknown> })
		?.probabilities;
	if ((answer as { type?: string })?.type !== "choice" || !probs || typeof probs !== "object") {
		return null;
	}
	const order = candidates
		.map((c) => ({ url: c.url, p: probs[c.url] }))
		.filter((x): x is { url: string; p: number } => typeof x.p === "number");
	if (order.length !== candidates.length) return null; // missing options = malformed
	return order.sort((a, b) => b.p - a.p).map((x) => x.url);
}

/**
 * Related links for one reference page. `url` of a non-reference page yields
 * an empty list. Jev re-rank only runs with ORK_SITE_JEV_RERANK on and a key;
 * every failure mode falls back to the deterministic order.
 */
export async function getRelatedPages(
	page: { url: string; title: string },
	opts: { env?: NodeJS.ProcessEnv; fetchImpl?: typeof fetch } = {},
): Promise<RelatedItem[]> {
	const env = opts.env ?? process.env;
	const pool = candidatePool();
	const self = pool.find((c) => c.url === page.url);
	if (!self) return [];

	const base = deterministicRelated(self, pool, RELATED_GRAPH).map((c) => ({
		url: c.url,
		title: c.title,
	}));

	if (!jevRerankEnabled(env)) return base;

	const shortlist = deterministicRelated(self, pool, RELATED_GRAPH, {
		min: 0,
		max: JEV_CANDIDATE_LIMIT,
	}).map((c) => ({ url: c.url, title: c.title }));
	const order = await jevRerankOrder(page, shortlist, {
		fetchImpl: opts.fetchImpl,
		apiKey: env.TYPESAFE_API_KEY,
	});
	if (!order) return base;

	const byUrl = new Map(pool.map((c) => [c.url, c]));
	const reranked = order
		.map((u) => byUrl.get(u))
		.filter((c): c is RelatedCandidate => Boolean(c))
		.map((c) => ({ url: c.url, title: c.title }));
	return reranked.length >= 3 ? reranked.slice(0, 5) : base;
}
